-- DILEMA TEENS: 48 new catalog cards, 144 authored GIROS.
-- Idempotent data seed. Exact questions/intro prefixes guard duplicate writes.
begin;
create temporary table _teen_seed on commit drop as
select * from jsonb_to_recordset($catalog$[{"source_no":26,"audience":"teen","category":"REDES","debate_theme":"¿A QUIÉN SALVAS?","intensity":1,"question":"BORRAR UNO. Van a publicar dos vídeos: uno en el que tú haces el ridículo y otro en el que lo hace una amiga. Te dejan borrar uno antes de publicarlos; el otro se subirá. ¿A quién salvas del ridículo?","option_a":"A MÍ","option_b":"A MI AMIGA","giros":[{"text":"Tu amiga se ríe de su propio vídeo y te pide que borres el tuyo.","pressure":"A"},{"text":"El tuyo es mucho más gracioso, pero el suyo le avergüenza mucho más.","pressure":"B"},{"text":"Ella salvó un vídeo tuyo en una situación parecida hace meses.","pressure":"B"}]},{"source_no":27,"audience":"teen","category":"INSTI","debate_theme":"¿A QUIÉN SALVAS?","intensity":2,"question":"LA PLAZA. Tienes una única plaza para un viaje escolar muy deseado. Puedes cederla a tu mejor amiga, que se quedó fuera por un error del centro, pero si lo haces no habrá otra plaza para ti. ¿A quién se la das?","option_a":"ME LA QUEDO","option_b":"SE LA CEDO","giros":[{"text":"Ella ya hizo ese viaje hace años con su familia.","pressure":"A"},{"text":"Tú nunca has salido del país.","pressure":"A"},{"text":"Ella fue quien te animó a apuntarte cuando dudabas.","pressure":"B"}]},{"source_no":28,"audience":"teen","category":"ÉTICA","debate_theme":"¿A QUIÉN SALVAS?","intensity":2,"question":"EL ÚLTIMO ASIENTO. Solo queda un asiento en un autobús de evacuación. Tu compañera está lesionada y avanzará muy despacio a pie; un desconocido adulto parece sano, pero afirma que tiene una enfermedad que no se ve. Solo puedes decidir a quién cedes el asiento; el otro tendrá que ir andando y recibirá ayuda en el siguiente punto. ¿A quién eliges?","option_a":"A MI COMPAÑERA","option_b":"AL DESCONOCIDO","giros":[{"text":"La lesión de tu compañera es muy dolorosa, pero no permanente.","pressure":"A"},{"text":"El desconocido muestra medicación para una enfermedad seria.","pressure":"B"},{"text":"Tu compañera insiste en que el asiento sea para él.","pressure":"B"}]},{"source_no":29,"audience":"teen","category":"ÉTICA","debate_theme":"¿A QUIÉN SALVAS?","intensity":3,"question":"DIEZ AL AZAR. Puedes impedir que mueran diez personas elegidas al azar. Para hacerlo debes salvar a una persona condenada por asesinato que iba a morir hoy; si sobrevive, seguirá cumpliendo condena. La persona condenada no causó el peligro para las otras diez. No puedes salvar a ambas partes. ¿La salvas?","option_a":"LA SALVO","option_b":"NO LA SALVO","giros":[{"text":"Sabrás la identidad de las diez personas solo después de decidir.","pressure":"LATERAL"},{"text":"Una de las víctimas del asesino te pide que lo salves.","pressure":"A"},{"text":"El asesino no muestra ningún arrepentimiento.","pressure":"B"}]},{"source_no":30,"audience":"teen","category":"INSTI","debate_theme":"¿LO CUENTAS?","intensity":1,"question":"LA TIRITA. La persona que te gusta entra en clase con una tirita pegada a la espalda del jersey y nadie se ha atrevido a avisarle. Si lo haces delante del grupo, todo el mundo mirará. ¿Se lo dices ahora?","option_a":"SE LO DIGO","option_b":"ME CALLO","giros":[{"text":"Está a punto de salir en una foto de clase.","pressure":"A"},{"text":"La tirita se caerá sola antes de la foto y esa persona odia que la interrumpan delante de otros.","pressure":"B"},{"text":"Esa persona te pide que le digas si ves algo raro en su ropa.","pressure":"A"}]},{"source_no":31,"audience":"teen","category":"INSTI","debate_theme":"¿LO CUENTAS?","intensity":2,"question":"EL EXAMEN FILTRADO. Recibes por error una foto del examen de mañana. No la has abierto. Sabes que varios compañeros ya la están utilizando. Si avisas al profesor, probablemente se cancelará el examen y habrá una investigación. ¿Lo cuentas?","option_a":"LO CUENTO","option_b":"NO LO CUENTO","giros":[{"text":"Uno de quienes la usan es tu mejor amigo.","pressure":"B"},{"text":"El profesor explica que la nota decidirá una beca.","pressure":"A"},{"text":"Un compañero inocente está siendo acusado de la filtración.","pressure":"A"}]},{"source_no":32,"audience":"teen","category":"REDES","debate_theme":"¿LO CUENTAS?","intensity":2,"question":"LA CUENTA FALSA. Descubres quién lleva una cuenta anónima que se burla de compañeros del instituto. Es alguien que te defendió cuando tú lo pasaste mal. La persona más atacada te pregunta si sabes quién es. ¿Das su nombre?","option_a":"LO DIGO","option_b":"NO LO DIGO","giros":[{"text":"La cuenta sigue publicando cosas nuevas.","pressure":"A"},{"text":"El responsable promete cerrarla hoy.","pressure":"B"},{"text":"Una publicación contiene una mentira que ya está teniendo consecuencias fuera del instituto.","pressure":"A"}]},{"source_no":33,"audience":"teen","category":"ÉTICA","debate_theme":"¿LO CUENTAS?","intensity":3,"question":"LA DECLARACIÓN. Viste un accidente mortal y puedes demostrar que una persona inocente no lo causó. Para hacerlo tendrás que entregar una grabación que también demuestra que tú cometiste una imprudencia grave. Si la entregas, afrontas varios años de cárcel; si callas, la persona inocente cumplirá esa condena. ¿Entregas la grabación?","option_a":"LA ENTREGO","option_b":"CALLO","giros":[{"text":"La persona inocente tiene una condena previa y nadie le cree.","pressure":"A"},{"text":"Otra persona sabe que tienes la grabación.","pressure":"A"},{"text":"La persona inocente se niega a pedirte que te sacrifiques.","pressure":"B"}]},{"source_no":34,"audience":"teen","category":"OCIO","debate_theme":"¿TRAICIONAS?","intensity":1,"question":"EL BAILE. Prometiste ensayar con una amiga una coreografía para la fiesta. La persona que te gusta te propone formar pareja contigo esa misma tarde y no habrá otra ocasión. ¿Rompes tu promesa?","option_a":"SÍ","option_b":"NO","giros":[{"text":"Tu amiga rechazó otra pareja por ensayar contigo.","pressure":"B"},{"text":"La persona que te gusta acepta esperar solo diez minutos.","pressure":"A"},{"text":"Tu amiga hizo lo mismo contigo el año pasado.","pressure":"A"}]},{"source_no":35,"audience":"teen","category":"DEPORTE","debate_theme":"¿TRAICIONAS?","intensity":2,"question":"EL PLAN B. Tu mejor amigo te cuenta en secreto que quiere dejar el equipo al final de la temporada. El entrenador va a elegir mañana al capitán y está a punto de darle el puesto. Si callas, otro compañero que desea el puesto podría perderlo. ¿Revelas el plan de tu amigo?","option_a":"LO REVELO","option_b":"GUARDO EL SECRETO","giros":[{"text":"Tu amigo aún no ha tomado la decisión definitiva.","pressure":"B"},{"text":"El otro compañero te pide que hables con el entrenador.","pressure":"A"},{"text":"El entrenador te pregunta directamente si sabes algo.","pressure":"A"}]},{"source_no":36,"audience":"teen","category":"AMIGOS","debate_theme":"¿TRAICIONAS?","intensity":2,"question":"LA COARTADA. Tu amiga te pide que confirmes que estaba contigo cuando en realidad no lo estaba. No sabes por qué quiere ocultarlo. Si dices la verdad, probablemente se enfadará contigo. ¿La cubres?","option_a":"LA CUBRO","option_b":"DIGO LA VERDAD","giros":[{"text":"Descubres que estaba preparando una sorpresa para otra persona.","pressure":"A"},{"text":"Sabes que alguien está siendo acusado injustamente por su ausencia.","pressure":"B"},{"text":"Ella te dice que lo hizo para evitar una conversación difícil en casa.","pressure":"A"}]},{"source_no":37,"audience":"teen","category":"ÉTICA","debate_theme":"¿TRAICIONAS?","intensity":3,"question":"EL CULPABLE INCORRECTO. Una amiga admite que provocó un incendio mortal por imprudencia. Otra persona inocente está a punto de cumplir una larga condena por ello. Tu amiga te suplica que guardes el secreto: si la señalas, será ella quien pase años en prisión y vuestra amistad terminará para siempre. ¿La delatas?","option_a":"SÍ","option_b":"NO","giros":[{"text":"Tu amiga asegura que confesará si le das una semana.","pressure":"B"},{"text":"La persona inocente ya ha perdido su trabajo.","pressure":"A"},{"text":"Tu amiga te recuerda que estabas allí y podrías ser investigado también.","pressure":"B"}]},{"source_no":38,"audience":"teen","category":"INSTI","debate_theme":"¿TE METES?","intensity":1,"question":"EL APELLIDO. El profesor lleva semanas pronunciando mal el apellido de un compañero. Él nunca lo corrige, pero se nota que le molesta. ¿Interrumpes para corregirlo tú?","option_a":"SÍ","option_b":"NO","giros":[{"text":"Tu compañero te pidió que no hicieras un espectáculo.","pressure":"B"},{"text":"El profesor acaba de pedir que se le corrija si dice mal algún nombre.","pressure":"A"},{"text":"Varios compañeros han empezado a copiar la pronunciación equivocada.","pressure":"A"}]},{"source_no":39,"audience":"teen","category":"INSTI","debate_theme":"¿TE METES?","intensity":2,"question":"LA BROMA PRIVADA. Un grupo prepara una broma sobre una compañera que ella todavía no conoce. Nadie piensa hacerle daño, pero tú crees que se sentirá humillada. Si intentas pararla, tus amigos dirán que siempre estropeas los planes. ¿Te metes?","option_a":"LA PARO","option_b":"NO ME METO","giros":[{"text":"Descubres que la broma incluye grabarla.","pressure":"A"},{"text":"La compañera hizo una broma parecida al grupo.","pressure":"B"},{"text":"Uno de los organizadores admite en privado que a él también le parece excesiva.","pressure":"A"}]},{"source_no":40,"audience":"teen","category":"INSTI","debate_theme":"¿TE METES?","intensity":2,"question":"EL REPARTO. En un trabajo de grupo, una persona está haciendo casi todo y las demás se llevarán la misma nota. Tú no perteneces a ese grupo, pero puedes hablar con el profesor antes de la entrega. ¿Intervienes?","option_a":"SÍ","option_b":"NO","giros":[{"text":"Quien hace todo te pide que no digas nada.","pressure":"B"},{"text":"El profesor va a pedir una valoración individual.","pressure":"B"},{"text":"Entregarán mañana y el profesor pondrá la misma nota a todos sin conocer cómo se repartió el trabajo.","pressure":"A"}]},{"source_no":41,"audience":"teen","category":"ÉTICA","debate_theme":"¿TE METES?","intensity":3,"question":"LA PUERTA. Ves que alguien ha quedado atrapado en un incendio. Puedes abrir una puerta para sacarlo, pero al hacerlo las llamas alcanzarán otra estancia y morirá una segunda persona. Si no intervienes, la primera persona morirá y la segunda estará a salvo. No hay tiempo para otro rescate. ¿Abres la puerta?","option_a":"LA ABRO","option_b":"NO LA ABRO","giros":[{"text":"La persona atrapada te salvó la vida una vez y ahora te está pidiendo que abras.","pressure":"A"},{"text":"Quien está en la otra estancia aún no conoce el riesgo.","pressure":"B"},{"text":"La segunda persona había entrado para avisar a otros del incendio.","pressure":"B"}]},{"source_no":42,"audience":"teen","category":"OCIO","debate_theme":"¿QUÉ SACRIFICAS?","intensity":1,"question":"EL CONCIERTO. Te regalan una entrada para el concierto de tu artista favorito, justo la noche del cumpleaños de una amiga que lleva meses preparándolo. No puedes llegar a los dos. ¿Qué sacrificas?","option_a":"EL CONCIERTO","option_b":"EL CUMPLEAÑOS","giros":[{"text":"Tu amiga entiende que es una ocasión única y te anima a ir al concierto.","pressure":"B"},{"text":"Hace un año faltó a tu cumpleaños por un plan menos importante.","pressure":"B"},{"text":"Sabes que te ha preparado una sorpresa.","pressure":"A"}]},{"source_no":43,"audience":"teen","category":"FUTURO","debate_theme":"¿QUÉ SACRIFICAS?","intensity":2,"question":"LA BECA. Te ofrecen una beca excelente para estudiar fuera durante un año. Debes aceptarla hoy. Si te vas, perderás tu puesto en el equipo con el que llevas años intentando llegar a una final. ¿Qué eliges?","option_a":"LA BECA","option_b":"EL EQUIPO","giros":[{"text":"La beca no volverá a ofrecerse.","pressure":"A"},{"text":"Tus compañeros lleváis años preparando juntos esta última temporada antes de separaros.","pressure":"B"},{"text":"Allí podrás seguir entrenando, pero con otro equipo.","pressure":"A"}]},{"source_no":44,"audience":"teen","category":"REDES","debate_theme":"¿QUÉ SACRIFICAS?","intensity":2,"question":"LA VERDAD SOBRE TI. Puedes borrar de internet una mentira muy dañina sobre ti. Al hacerlo también desaparecerán para siempre todas las publicaciones y mensajes de apoyo que recibiste cuando ocurrió. Nadie conservará una copia. ¿Lo borras todo?","option_a":"SÍ","option_b":"NO","giros":[{"text":"La mentira sigue apareciendo cuando buscan tu nombre.","pressure":"A"},{"text":"Uno de esos mensajes de apoyo es de alguien con quien ya no puedes hablar.","pressure":"B"},{"text":"Tus amigos prometen escribirte mensajes nuevos, pero no serán los originales.","pressure":"A"}]},{"source_no":45,"audience":"teen","category":"ÉTICA","debate_theme":"¿QUÉ SACRIFICAS?","intensity":3,"question":"LA MEMORIA. Puedes salvar a una persona desconocida que morirá esta noche. El precio es perder para siempre todos tus recuerdos personales anteriores a hoy: reconocerás el idioma y sabrás vivir por tu cuenta, pero no recordarás a nadie de tu vida ni nada de lo que habéis compartido. ¿Lo haces?","option_a":"SALVO A LA PERSONA","option_b":"CONSERVO MIS RECUERDOS","giros":[{"text":"La persona desconocida sabe lo que perderías y te pide que no lo hagas.","pressure":"B"},{"text":"Tus seres queridos conservarán todos sus recuerdos contigo.","pressure":"A"},{"text":"Te dicen que podrás construir recuerdos nuevos con ellos, aunque los antiguos no regresarán.","pressure":"A"}]},{"source_no":46,"audience":"teen","category":"OCIO","debate_theme":"¿ACEPTAS EL TRATO?","intensity":1,"question":"EL BOTÓN DEL RIDÍCULO. Si pulsas un botón, nunca más volverás a sentir vergüenza. A cambio, una vez al mes cometerás un ridículo enorme delante de alguien que conoces, y no podrás evitarlo. ¿Lo pulsas?","option_a":"SÍ","option_b":"NO","giros":[{"text":"Nunca sabrás qué día ocurrirá.","pressure":"B"},{"text":"Tampoco sentirás vergüenza por el ridículo después.","pressure":"A"},{"text":"Una persona de tu grupo podrá verlo siempre.","pressure":"B"}]},{"source_no":47,"audience":"teen","category":"DINERO","debate_theme":"¿ACEPTAS EL TRATO?","intensity":2,"question":"MILLONARIO SIN ELLOS. Puedes ser millonario desde hoy y durante toda tu vida. A cambio, tus familiares y amigos actuales dejarán de formar parte de tu vida y no podrás volver a relacionarte con ellos. Podrás conocer y querer a personas nuevas. ¿Aceptas?","option_a":"ACEPTO","option_b":"RECHAZO","giros":[{"text":"Ellos conservarán todos sus recuerdos contigo.","pressure":"B"},{"text":"Tendrás que decidir hoy sin despedirte.","pressure":"B"},{"text":"Podrás asegurarles una vida económicamente cómoda antes de separaros.","pressure":"A"}]},{"source_no":48,"audience":"teen","category":"ÉTICA","debate_theme":"¿ACEPTAS EL TRATO?","intensity":2,"question":"CUÁNDO O CÓMO. Te obligan a conocer una verdad exacta sobre tu muerte. Puedes saber la fecha o la causa, pero no ambas. Ninguna de las dos se puede cambiar. ¿Cuál eliges saber?","option_a":"CUÁNDO","option_b":"CÓMO","giros":[{"text":"Si eliges la causa, podría ser algo que haces habitualmente.","pressure":"A"},{"text":"Si eliges la fecha, tendrás que celebrarla cada año al llegar ese día del calendario.","pressure":"B"},{"text":"Podrás contar lo que sabes, pero nadie tendrá forma de comprobarlo antes.","pressure":"LATERAL"}]},{"source_no":49,"audience":"teen","category":"WTF","debate_theme":"¿ACEPTAS EL TRATO?","intensity":3,"question":"EL RITUAL. Sabes con certeza que morirás dentro de diez años. Puedes evitar esa muerte si, desde mañana y durante el resto de tu vida, bebes cada día un vaso de agua con una cucharada de saliva de otra persona. Si fallas un solo día, volverás a morir al cumplirse los diez años. No hay otra forma de impedirlo. ¿Aceptas?","option_a":"ACEPTO","option_b":"RECHAZO","giros":[{"text":"Varias personas de confianza se ofrecen a ayudarte a cumplir el ritual durante el primer mes.","pressure":"A"},{"text":"Deberás conseguir la saliva por tu cuenta, con el consentimiento de quien te la dé.","pressure":"B"},{"text":"Cada semana deberá dártela una persona distinta.","pressure":"B"}]},{"source_no":50,"audience":"teen","category":"ÉTICA","debate_theme":"¿A QUIÉN SALVAS?","intensity":3,"question":"UNO QUE CONOCES, TRES QUE NO. Un rescate solo puede llegar a una de dos habitaciones. En una está un amigo tuyo. En la otra hay tres desconocidos. Quien no reciba ayuda morirá; nadie ha provocado la situación. ¿A quién salvas?","option_a":"A MI AMIGO","option_b":"A LOS TRES","giros":[{"text":"Tu amigo sabe que hay otras tres personas.","pressure":"B"},{"text":"Una de las tres está consciente y te pide que vayas primero a por tu amigo.","pressure":"A"},{"text":"Si salvas a los tres, sus familias sabrán que elegiste esa habitación.","pressure":"B"}]},{"source_no":51,"audience":"teen","category":"ÉTICA","debate_theme":"¿A QUIÉN SALVAS?","intensity":3,"question":"UNA VIDA SEGURA. Hay medicina suficiente para una sola decisión: una persona tiene el 90 % de probabilidades de sobrevivir si la recibe; otras dos tienen, cada una, el 40 % si se reparte entre ellas. Sin medicina, las tres morirán. La asignación se hará exactamente como tú indiques. ¿A quién das la medicina?","option_a":"A LA PERSONA DEL 90 %","option_b":"A LAS DOS DEL 40 %","giros":[{"text":"Una de las dos personas del 40 % es mucho más joven.","pressure":"B"},{"text":"La persona del 90 % te pide que repartas la medicina.","pressure":"B"},{"text":"Las dos del 40 % no saben que existe la opción de concentrarla.","pressure":"A"}]},{"source_no":52,"audience":"teen","category":"ÉTICA","debate_theme":"¿A QUIÉN SALVAS?","intensity":3,"question":"EL RESPONSABLE. Tras un accidente, solo puedes sacar a una persona antes de que se hunda el vehículo. Una es quien conducía y causó el accidente por una imprudencia grave. La otra es una pasajera que no tuvo culpa. Ambas morirán sin tu ayuda. ¿A quién salvas?","option_a":"A QUIEN CONDUCÍA","option_b":"A LA PASAJERA","giros":[{"text":"Quien conducía admite su culpa.","pressure":"B"},{"text":"La pasajera te pide que salves a la otra persona.","pressure":"A"},{"text":"Quien conducía es la única persona que puede explicar cómo ocurrió el accidente.","pressure":"A"}]},{"source_no":53,"audience":"teen","category":"ÉTICA","debate_theme":"¿A QUIÉN SALVAS?","intensity":3,"question":"EL RESCATADOR. Puedes sacar ahora a dos personas atrapadas y dejar atrás a una tercera que es rescatadora profesional. O puedes sacar a la rescatadora primero: si sobrevive, tendrá un 50 % de posibilidades de volver y salvar a las otras dos. Si falla, morirán ambas. Tú no puedes hacer un segundo viaje. ¿A quién salvas primero?","option_a":"A LAS DOS","option_b":"A LA RESCATADORA","giros":[{"text":"La rescatadora te pide que asegures las dos vidas.","pressure":"A"},{"text":"Una de las dos personas es también rescatadora, pero está lesionada y no podrá volver.","pressure":"A"},{"text":"La rescatadora conoce personalmente a las dos personas atrapadas.","pressure":"B"}]},{"source_no":54,"audience":"teen","category":"ÉTICA","debate_theme":"¿LO CUENTAS?","intensity":3,"question":"EL TESTIGO. Una grabación demuestra que un acusado de homicidio es inocente. También identifica a la única persona que se atrevió a declarar contra un grupo violento, que se esconde para seguir con vida. Si entregas la grabación, el acusado quedará libre y el testigo será localizado. Si callas, el acusado pasará años en prisión. ¿La entregas?","option_a":"LA ENTREGO","option_b":"CALLO","giros":[{"text":"El testigo te pide que no entregues la grabación.","pressure":"B"},{"text":"El acusado ya ha pasado años encerrado por un crimen que no cometió.","pressure":"B"},{"text":"El grupo violento ya está buscando al testigo sin éxito.","pressure":"A"}]},{"source_no":55,"audience":"teen","category":"ÉTICA","debate_theme":"¿LO CUENTAS?","intensity":3,"question":"LA CONFESIÓN PÚBLICA. Tú y otra persona cometisteis una imprudencia que dejó a alguien con una lesión permanente. La otra persona ha asumido toda la culpa. Puedes contar lo que hiciste y evitar que cumpla sola una larga condena, pero entonces los dos la cumpliréis. Si callas, nunca podrá demostrar que participaste. ¿Lo cuentas?","option_a":"CONFIESO","option_b":"CALLO","giros":[{"text":"La persona que asumió la culpa te dice que no confieses.","pressure":"B"},{"text":"Quien sufrió la lesión cree que fuiste inocente.","pressure":"B"},{"text":"La condena de la otra persona empezará mañana.","pressure":"A"}]},{"source_no":56,"audience":"teen","category":"ÉTICA","debate_theme":"¿LO CUENTAS?","intensity":3,"question":"EL ÚLTIMO MENSAJE. Una persona a la que aprecias ha dejado escrito que no quiere conocer el pronóstico exacto de una enfermedad incurable. Tú sabes que le quedan pocas semanas y que mañana tomará una decisión irreversible sobre su futuro basándose en que le quedan años. ¿Le dices la verdad pese a su petición expresa?","option_a":"SE LO DIGO","option_b":"RESPETO SU PETICIÓN","giros":[{"text":"Te vuelve a pedir que no le des cifras.","pressure":"B"},{"text":"La decisión de mañana afecta también a otra persona.","pressure":"A"},{"text":"Podría aplazarla una semana si supiera la verdad.","pressure":"A"}]},{"source_no":57,"audience":"teen","category":"ÉTICA","debate_theme":"¿LO CUENTAS?","intensity":3,"question":"TU NOMBRE EN LA LISTA. Conoces los nombres de quienes van a recibir una oportunidad de huir de una catástrofe. Descubres que hay un error: tu nombre figura en lugar del de una persona que tenía derecho a esa plaza. Si señalas el error, ella saldrá y tú te quedarás. Si callas, nadie lo descubrirá antes de partir. ¿Lo cuentas?","option_a":"SEÑALO EL ERROR","option_b":"CALLO","giros":[{"text":"La persona cuyo nombre fue sustituido tenía la plaza confirmada por escrito.","pressure":"A"},{"text":"Te garantizan que quien se quede tendrá una posibilidad pequeña de sobrevivir.","pressure":"B"},{"text":"Quien hizo la lista fue un amigo tuyo.","pressure":"LATERAL"}]},{"source_no":58,"audience":"teen","category":"ÉTICA","debate_theme":"¿TRAICIONAS?","intensity":3,"question":"EL PACTO. Cuatro amigos hicisteis un pacto para no revelar quién causó un accidente mortal. Una persona inocente está a punto de ser condenada. Si rompes el pacto, los cuatro seréis investigados y perderás para siempre su confianza; si lo mantienes, la persona inocente irá a prisión. ¿Rompes el pacto?","option_a":"LO ROMPO","option_b":"LO MANTENGO","giros":[{"text":"Uno de tus amigos quería confesar desde el principio.","pressure":"A"},{"text":"Otro te recuerda que fuiste tú quien propuso el pacto.","pressure":"B"},{"text":"La persona inocente conoce a uno de vosotros.","pressure":"A"}]},{"source_no":59,"audience":"teen","category":"ÉTICA","debate_theme":"¿TRAICIONAS?","intensity":3,"question":"LA LLAVE. Tu mejor amigo te confió la ubicación de una llave y te hizo prometer que nunca la usarías. Ahora esa llave permite abrir un refugio donde están atrapadas varias personas. Si entras, también se revelará un secreto suyo que le costará una larga condena. No hay tiempo para pedirle permiso. ¿Usas la llave?","option_a":"LA USO","option_b":"CUMPLO LA PROMESA","giros":[{"text":"Tu amigo está entre las personas atrapadas.","pressure":"A"},{"text":"Tu amigo te confió esa llave precisamente porque pensó que nunca abrirías el refugio sin consultarle.","pressure":"B"},{"text":"Tu amigo te había dicho que prefería pagar por sus actos antes que causar daño a otros.","pressure":"A"}]},{"source_no":60,"audience":"teen","category":"ÉTICA","debate_theme":"¿TRAICIONAS?","intensity":3,"question":"EL NOMBRE DEL INFORMANTE. Un amigo te contó en secreto que está pasando información para impedir un ataque. Sus datos pueden detenerlo hoy, pero solo si dices quién es: quedará identificado y afrontará represalias graves. Si proteges su nombre, el ataque causará varias muertes. No puedes contactar con él a tiempo. ¿Lo identificas?","option_a":"DOY SU NOMBRE","option_b":"LO PROTEJO","giros":[{"text":"Tu amigo entró voluntariamente en esa situación.","pressure":"A"},{"text":"Te dijo expresamente que jamás dieras su nombre.","pressure":"B"},{"text":"Puede que descubran su identidad igualmente después del ataque.","pressure":"A"}]},{"source_no":61,"audience":"teen","category":"ÉTICA","debate_theme":"¿TRAICIONAS?","intensity":3,"question":"EL CÓDIGO COMPARTIDO. Tú y una amiga compartís un código que da acceso a un único tratamiento. Ella te pidió que lo guardaras para sí misma si llegaba a necesitarlo. Ahora lo necesita, pero también lo necesitan dos desconocidos. Puedes usar el código para ellos antes de que ella llegue; entonces no habrá tratamiento para tu amiga. ¿Rompes vuestra promesa?","option_a":"LO USO PARA LOS DOS","option_b":"LO RESERVO PARA ELLA","giros":[{"text":"Tu amiga te dice por teléfono que cumplas lo prometido.","pressure":"B"},{"text":"Uno de los desconocidos podría sobrevivir sin tratamiento, pero no se sabe cuál.","pressure":"B"},{"text":"Tu amiga había compartido el código contigo para que pudieras decidir en su ausencia.","pressure":"A"}]},{"source_no":62,"audience":"teen","category":"ÉTICA","debate_theme":"¿TE METES?","intensity":3,"question":"LA COMPUERTA. Una compuerta está cerrada y mantiene a salvo a una persona. Al otro lado, tres personas morirán si no la abres. Abrirla permitirá salir a las tres, pero la persona que estaba protegida morirá. Nadie más puede intervenir. ¿La abres?","option_a":"LA ABRO","option_b":"NO ME METO","giros":[{"text":"La persona protegida oye tu conversación.","pressure":"B"},{"text":"Una de las tres personas había entrado para avisar a otras del peligro.","pressure":"A"},{"text":"Si no intervienes, nadie sabrá que podías abrirla.","pressure":"B"}]},{"source_no":63,"audience":"teen","category":"ÉTICA","debate_theme":"¿TE METES?","intensity":3,"question":"LA DECISIÓN DEL PACIENTE. Una persona consciente rechaza el único tratamiento que podría salvarle la vida. Puedes activar un mecanismo que se lo administrará de inmediato, contra su voluntad; sobrevivirá, pero quedará con una secuela permanente. Si respetas su decisión, morirá hoy. En este escenario no hay otra intervención posible. ¿Lo activas?","option_a":"LO ACTIVO","option_b":"RESPETO SU DECISIÓN","giros":[{"text":"La persona conoce y entiende todas las consecuencias.","pressure":"B"},{"text":"La secuela le impediría hacer aquello a lo que ha dedicado su vida.","pressure":"B"},{"text":"Un ser querido te pide que actives el mecanismo.","pressure":"A"}]},{"source_no":64,"audience":"teen","category":"ÉTICA","debate_theme":"¿TE METES?","intensity":3,"question":"LA ALERTA. Detectas una alarma que anuncia una catástrofe real. Puedes activarla y evacuar a cientos de personas, pero el protocolo cerrará automáticamente una zona y dos personas que están dentro morirán. Si no la activas, esas dos vivirán y morirán decenas en el resto del edificio. ¿Activas la alarma?","option_a":"LA ACTIVO","option_b":"NO INTERVENGO","giros":[{"text":"Las dos personas conocen el protocolo.","pressure":"A"},{"text":"Una de ellas es quien detectó primero el peligro.","pressure":"B"},{"text":"La gente de fuera todavía no sabe que hay una emergencia.","pressure":"A"}]},{"source_no":65,"audience":"teen","category":"ÉTICA","debate_theme":"¿TE METES?","intensity":3,"question":"LA TURBA. Una multitud está a punto de golpear hasta matar a una persona a la que acusa de un crimen sin pruebas. Puedes interponerte y detenerla, pero sabes con certeza que sufrirás una lesión permanente en una pierna. Si no intervienes, la persona morirá. Nadie más se atreve a actuar. ¿Te metes?","option_a":"ME METO","option_b":"NO ME METO","giros":[{"text":"La persona atacada había sido acusada falsamente una vez antes.","pressure":"A"},{"text":"Una de las personas de la multitud es amiga tuya.","pressure":"B"},{"text":"Te garantizan que interponerte detendrá el ataque antes de que haya más víctimas.","pressure":"A"}]},{"source_no":66,"audience":"teen","category":"ÉTICA","debate_theme":"¿QUÉ SACRIFICAS?","intensity":3,"question":"CINCO AÑOS. Puedes salvar a dos personas desconocidas que morirán hoy. El precio es perder con certeza cinco años de tu propia vida, aunque no sabrás cuáles habrían sido. No afectará a nadie más. ¿Los entregas?","option_a":"ENTREGO CINCO AÑOS","option_b":"CONSERVO MI VIDA","giros":[{"text":"Una de las dos personas te pide que no pagues ese precio.","pressure":"B"},{"text":"No tendrás ninguna señal física de los años perdidos.","pressure":"A"},{"text":"Los dos sabrán lo que decidiste.","pressure":"A"}]},{"source_no":67,"audience":"teen","category":"ÉTICA","debate_theme":"¿QUÉ SACRIFICAS?","intensity":3,"question":"TU VOZ. Puedes evitar que una persona muera, pero perderás permanentemente la capacidad de hablar y cantar. Podrás comunicarte por escrito y con gestos. Si rechazas el intercambio, esa persona morirá hoy. ¿Qué sacrificas?","option_a":"MI VOZ","option_b":"ESA VIDA","giros":[{"text":"La persona es una desconocida.","pressure":"B"},{"text":"Escucharás tu voz grabada siempre que quieras, aunque no podrás recuperarla.","pressure":"A"},{"text":"Esa persona te pide que conserves tu voz.","pressure":"B"}]},{"source_no":68,"audience":"teen","category":"ÉTICA","debate_theme":"¿QUÉ SACRIFICAS?","intensity":3,"question":"LA ALEGRÍA. Puedes salvar a cinco personas, pero dejarás de sentir alegría durante el resto de tu vida. Conservarás la memoria, el afecto, la tristeza y la capacidad de tomar decisiones. Si no aceptas, esas cinco personas morirán. ¿Entregas esa parte de ti?","option_a":"RENUNCIO A LA ALEGRÍA","option_b":"NO ACEPTO","giros":[{"text":"Seguirás pudiendo reconocer cuándo otras personas son felices.","pressure":"A"},{"text":"Nadie podrá revertir el cambio.","pressure":"B"},{"text":"Los cinco conocerán el precio que pagaste.","pressure":"A"}]},{"source_no":69,"audience":"teen","category":"ÉTICA","debate_theme":"¿QUÉ SACRIFICAS?","intensity":3,"question":"DIEZ AÑOS ENCERRADO. Puedes impedir la muerte de tres desconocidos si aceptas pasar los próximos diez años encerrado y sin visitas. Sabrás que el tiempo fuera sigue pasando; al salir recuperarás tu libertad. Si rechazas el trato, morirán hoy. ¿Qué eliges?","option_a":"ENTREGO DIEZ AÑOS","option_b":"RECHAZO","giros":[{"text":"Podrás intercambiar una carta al mes, pero no recibir respuesta.","pressure":"B"},{"text":"Nadie más puede ocupar tu lugar.","pressure":"A"},{"text":"Al salir conocerás a las tres personas que salvaste.","pressure":"A"}]},{"source_no":70,"audience":"teen","category":"ÉTICA","debate_theme":"¿ACEPTAS EL TRATO?","intensity":3,"question":"LA VIDA PRESTADA. Te ofrecen veinte años adicionales de vida sana. A cambio, una persona elegida al azar perderá veinte años de la suya; nunca sabrás quién fue. No puedes repartir los años ni avisarla. ¿Aceptas?","option_a":"ACEPTO","option_b":"RECHAZO","giros":[{"text":"La persona podría ser alguien que conoces.","pressure":"B"},{"text":"Hay alguien que depende de tus cuidados y esos años podrían permitirte seguir a su lado.","pressure":"A"},{"text":"Si aceptas, tú sí recordarás cada día su coste.","pressure":"B"}]},{"source_no":71,"audience":"teen","category":"ÉTICA","debate_theme":"¿ACEPTAS EL TRATO?","intensity":3,"question":"EL PRECIO DE LA CURA. Existe una cura definitiva para una enfermedad que padecen miles de personas. Puedes activarla hoy, pero cada año, durante diez años, morirá una persona sana elegida al azar como precio. Las diez muertes son seguras. Si no la activas, la enfermedad seguirá su curso. ¿Aceptas el trato?","option_a":"ACTIVO LA CURA","option_b":"LA RECHAZO","giros":[{"text":"Nunca conocerás la identidad de quienes pagan el precio.","pressure":"LATERAL"},{"text":"Las personas enfermas sí conocerán la condición de la cura.","pressure":"A"},{"text":"No podrás detener el proceso después de activarlo.","pressure":"B"}]},{"source_no":72,"audience":"teen","category":"ÉTICA","debate_theme":"¿ACEPTAS EL TRATO?","intensity":3,"question":"EL DOLOR TRANSFERIDO. Pueden eliminarte para siempre un dolor físico intenso que sufres a diario. El dolor pasará íntegro, también para siempre, a una persona sana elegida al azar. Esa persona no sabrá por qué le ocurrió. ¿Aceptas?","option_a":"ACEPTO","option_b":"RECHAZO","giros":[{"text":"El dolor ya te impide cuidar de una persona que depende de ti.","pressure":"A"},{"text":"La persona elegida podría tener tu edad.","pressure":"B"},{"text":"Si rechazas, nadie sabrá que podías librarte del dolor.","pressure":"B"}]},{"source_no":73,"audience":"teen","category":"DINERO","debate_theme":"¿ACEPTAS EL TRATO?","intensity":3,"question":"EL MILLÓN QUE COBRA OTRO. Te ofrecen un millón de euros ahora mismo. Cada euro que gastes se descontará en secreto de los ahorros de una persona distinta elegida al azar; si agotas sus ahorros, asumirá una deuda que no podrá cancelar. Nunca sabrás a quién afectas. ¿Aceptas el dinero?","option_a":"LO ACEPTO","option_b":"LO RECHAZO","giros":[{"text":"Puedes decidir no gastar nada una vez lo recibas.","pressure":"A"},{"text":"Una parte del dinero podría pagar un tratamiento urgente para alguien que conoces.","pressure":"A"},{"text":"Quien cargue con la deuda no sabrá nunca que tú elegiste el trato.","pressure":"B"}]}]$catalog$::jsonb) as r(source_no int,audience text,category text,debate_theme text,
intensity int,question text,option_a text,option_b text,giros jsonb);
