with new_rows as (
insert into public.dilemmas(audience,category,debate_theme,intensity,question,option_a,option_b,active)
select s.audience,s.category,s.debate_theme,s.intensity,s.question,s.option_a,s.option_b,true
from _teen_seed s where not exists(
select 1 from public.dilemmas d where d.audience=s.audience and d.question=s.question)
returning id,question)
insert into public.dilemma_twists(dilemma_id,text,pressure,active)
select d.id,t.text,t.pressure,true
from new_rows d join _teen_seed s on d.question=s.question
cross join lateral jsonb_to_recordset(s.giros) as t(text text,pressure text);
do $check$
declare cards int; twists int;
begin
select count(*),coalesce(sum(t.n),0) into cards,twists
from _teen_seed s join public.dilemmas d
on d.audience=s.audience and d.question=s.question
cross join lateral (select count(*) n from public.dilemma_twists x
where x.dilemma_id=d.id and x.active) t;
if cards<>48 or twists<144 then raise exception 'Catalog incomplete: % cards / % GIROS',cards,twists;end if;
